fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Helper: check if `n` is a power of two
    fn is_power_of_two(n: i32) -> bool {
        n > 0 && (n & (n - 1)) == 0
    }

    // Helper: "limited-prime" as defined in the problem statement
    // p <= 1          => not prime
    // p == 2          => prime
    // even p > 2      => not prime
    // odd p > 2       => prime
    fn is_limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else {
            p % 2 != 0
        }
    }

    let t = input.get(0)
        .cloned()
        .expect("Input must have at least one element") as usize;
    let mut result = Vec::with_capacity(t);

    for i in 0..t {
        let n = input[i + 1] as i32;
        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            "FastestFinger"
        } else if n % 4 != 2 {
            // Covers all odd n > 2 and all multiples of 4 that aren't powers of two
            "Ashishgup"
        } else {
            // n % 4 == 2 here, so n >= 6
            let p = n / 2;
            if is_limited_prime(p) {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };
        result.push(winner);
    }

    result
}

